SELECT jsonb_build_object('read13_marker','RuntimeReservation/positive/A'::text,'position','BEFORE'::text);
SELECT jsonb_build_object('model','RuntimeCommandReceipt','ids',coalesce(jsonb_agg(observed.id::text ORDER BY observed.id::text COLLATE "C"),'[]'::jsonb)) FROM (SELECT id,owner_module_id,operation,subject_scope,semantic_key,fingerprint,state,source_revision,result_schema_id,result_schema_version,result_digest,result_body,created_at,mutation_transaction_id FROM platform.runtime_command_receipt WHERE id IN ('7f470f9d-ffe1-5c29-ab7c-a48e3ea5a58d'::uuid)) observed;
SELECT jsonb_build_object('model','RuntimeReservation','ids',coalesce(jsonb_agg(observed.id::text ORDER BY observed.id::text COLLATE "C"),'[]'::jsonb)) FROM (SELECT id,command_receipt_id,owner_module_id,resource_kind,resource_key,semantic_key,quantity,state,fence,effect_receipt_id,expires_at,created_at,mutation_transaction_id FROM platform.runtime_reservation WHERE id IN ('86f9e299-8b77-5a44-9524-818666ece211'::uuid,'09be5411-0338-5038-8d04-12fabeb066df'::uuid)) observed;
SET CONSTRAINTS ALL IMMEDIATE;
SELECT jsonb_build_object('read13_marker','RuntimeReservation/positive/A'::text,'position','AFTER'::text);
